rows.map((c) =>
    c.name === collegeName
      ? { ...c, avg: Math.round((c.avg * c.members + userScore) / (c.members + 1)), members: c.members + 1 }
      : c
  ).sort

getClient().then((sb) => {
    if (!sb) {
      cb(null);
      return;
    }
    sb.auth.getSession().then(({ data }) => cb(data?.session?.user || null)).catch(() => cb(null));
    sb.auth.onAuthStateChange((_evt, session) => cb(session?.user || null));
  }).catch

